python3 -c "
import pikepdf
pdf = pikepdf.open('/root/sc100-blank.pdf')
print(f'Total pages: {len(pdf.pages)}')
print()
for page_num, page in enumerate(pdf.pages):
    if '/Annots' in page:
        annots = page['/Annots']
        print(f'=== Page {page_num} ({len(annots)} annotations) ===')
        for annot in annots:
            annot_obj = annot
            if isinstance(annot, pikepdf.Object):
                try:
                    annot_obj = pikepdf.Object.resolve(annot)
                except:
                    pass
            ft = str(annot_obj.get('/FT', '')) if '/FT' in annot_obj else ''
            t = str(annot_obj.get('/T', '')) if '/T' in annot_obj else ''
            v = str(annot_obj.get('/V', '')) if '/V' in annot_obj else ''
            subtype = str(annot_obj.get('/Subtype', ''))
            if ft:
                ftype = 'Text' if ft == '/Tx' else ('Button/Checkbox' if ft == '/Btn' else ('Choice' if ft == '/Ch' else ft))
                print(f'  Name={t}, Type={ftype}, Value={v}')
            elif subtype == '/Link':
                pass  # skip links
            else:
                # might be a widget without /FT, check parent
                pass
        print()
    else:
        print(f'=== Page {page_num}: No annotations ===')
        print()
"
